CREATE OR REPLACE FUNCTION public.media_submission_save_draft(p_submission uuid, p_data jsonb, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions; o submission_media.operations; f record;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);
 o:=submission_media.begin_operation(s.id,'save_workspace_draft',p_key,jsonb_build_object('data',p_data,'revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or p_revision<>s.workspace_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if exists(select 1 from submission_media.master_reviews where submission_id=s.id and state='pending') or (s.track_id is not null and not exists(select 1 from public.tracks where id=s.track_id and status='draft')) then raise exception 'Submitted workspace is read only' using errcode='42501';end if;
 if p_data is null or jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>40000 or (p_data-array['title','primaryArtist','featuredArtists','description','genre','subgenre','bpm','key','moods','language','releaseTitle','releaseDate','releaseYear','masterOwnership','masterOwners','publishingOwners','authority','hasSamples','samples','hasClaims','claims','hasAgreements','agreements','publishingOwnership','licensingAuthority','rightsNotes','permittedUses','restrictions','territories','licenseDuration','explicit','vocal','releaseStatus','contributors','rightsDeclared','licenseCategories'])<>'{}'::jsonb then raise exception 'Invalid draft' using errcode='22023';end if;
 for f in select * from (values ('title',160),('primaryArtist',200),('featuredArtists',1000),('description',3000),('genre',80),('subgenre',80),('bpm',3),('key',40),('moods',500),('language',35),('releaseTitle',200),('releaseDate',10),('releaseYear',4),('masterOwnership',2000),('publishingOwnership',2000),('licensingAuthority',2000),('rightsNotes',2000),('permittedUses',1000),('restrictions',2000),('territories',500),('licenseDuration',200)) fields(name,maximum) loop
  if jsonb_typeof(p_data->f.name) is distinct from 'string' or length(p_data->>f.name)>f.maximum or (p_data->>f.name)~'[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]' then raise exception 'Invalid draft field' using errcode='22023';end if;
 end loop;
 if coalesce(p_data->>'explicit','') not in ('unknown','clean','explicit') or coalesce(p_data->>'vocal','') not in ('unknown','instrumental','vocal','mixed') or coalesce(p_data->>'releaseStatus','') not in ('unreleased','released') or jsonb_typeof(p_data->'rightsDeclared') is distinct from 'boolean' or jsonb_typeof(p_data->'contributors') is distinct from 'array' or jsonb_typeof(p_data->'licenseCategories') is distinct from 'array' then raise exception 'Invalid draft classification' using errcode='22023';end if;
 if jsonb_array_length(p_data->'contributors')>30 or jsonb_array_length(p_data->'licenseCategories')>3 then raise exception 'Draft limit' using errcode='22023';end if;
 if exists(select 1 from jsonb_array_elements(p_data->'licenseCategories') c where jsonb_typeof(c) is distinct from 'string' or c#>>'{}' not in ('digital','broadcast','exclusive')) or exists(select 1 from jsonb_array_elements(p_data->'contributors') c where jsonb_typeof(c) is distinct from 'object' or c-array['name','role']<>'{}'::jsonb or jsonb_typeof(c->'name') is distinct from 'string' or length(c->>'name')>200 or coalesce(c->>'role','') not in ('writer','composer','producer','publisher','performer','other')) then raise exception 'Invalid contributors or preferences' using errcode='22023';end if;
 if s.workspace_draft ? 'publishingOwners' and not p_data ? 'publishingOwners' then raise exception 'Reload the updated rights workspace before saving' using errcode='22023';end if;
 perform submission_media.validate_master_owners(p_data->'masterOwners',false);
 perform submission_media.validate_workspace_rights(s.id,p_data,false);
 update submission_media.submissions set workspace_draft=p_data,workspace_revision=workspace_revision+1 where id=s.id;
 perform submission_media.append_event(s.id,'upload_metadata_saved',null,o.id,null,null,'artist');
 return submission_media.finish_operation(o.id,jsonb_build_object('draft_revision',s.workspace_revision+1,'revision',submission_media.bump(s.id)));
end $function$

CREATE OR REPLACE FUNCTION public.media_upload_playback(p_submission uuid, p_asset uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare s submission_media.submissions;a submission_media.assets;begin
 perform submission_media.require_capability('reads');if public.current_app_role()='admin' then perform submission_media.require_actor('admin');select * into s from submission_media.submissions where id=p_submission;else s:=submission_media.lock_owned(p_submission,null);end if;
 select * into a from submission_media.assets where submission_id=s.id and id=p_asset and kind in ('buyer_preview','waveform') and technical_state='ready' and source_asset_id=s.working_master_id;
 if not found or exists(select 1 from submission_media.upload_files where asset_id=a.source_asset_id and retired_at is not null) or not exists(select 1 from storage.objects where id=a.storage_object_id and version=a.storage_version and bucket_id=a.bucket and name=a.object_path) or not exists(select 1 from storage.buckets where id=a.bucket and not public) then raise exception 'Media unavailable' using errcode='42501';end if;
 return jsonb_build_object('asset_id',a.id,'bucket',a.bucket,'path',a.object_path,'sha256',encode(a.sha256,'hex'),'bytes',a.storage_bytes,'kind',a.kind,'version',a.storage_version);end$function$

CREATE OR REPLACE FUNCTION public.media_upload_remove(p_submission uuid, p_asset uuid, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare s submission_media.submissions; o submission_media.operations;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);o:=submission_media.begin_operation(s.id,'remove_upload',p_key,jsonb_build_object('asset',p_asset,'revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if not exists(select 1 from submission_media.upload_files where submission_id=s.id and asset_id=p_asset and retired_at is null) or p_asset in (s.current_master_id,s.current_preview_id,s.current_artwork_id) or exists(select 1 from submission_media.assets where id=p_asset and accepted_at is not null) or exists(select 1 from submission_media.master_reviews where submission_id=s.id and state='pending') or exists(select 1 from licensing_private.source_asset_links where master_id=p_asset) then raise exception 'Referenced media cannot be removed' using errcode='42501';end if;
 update submission_media.upload_files set retired_at=clock_timestamp(),retired_reason='removed' where asset_id=p_asset;
 update submission_media.assets set orphan_candidate_at=clock_timestamp() where id=p_asset;
 if s.working_master_id=p_asset then update submission_media.submissions set working_master_id=null,accepted_preview_id=null,selection_master_id=null,selection_start_ms=null,selection_end_ms=null where id=s.id;end if;
 perform submission_media.append_event(s.id,'upload_removed',p_asset,o.id,null,null,'artist');return submission_media.finish_operation(o.id,jsonb_build_object('revision',submission_media.bump(s.id)));end$function$

CREATE OR REPLACE FUNCTION public.media_upload_save_metadata(p_submission uuid, p_data jsonb, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare s submission_media.submissions; o submission_media.operations;t uuid;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);o:=submission_media.begin_operation(s.id,'save_upload_metadata',p_key,jsonb_build_object('data',p_data,'revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if jsonb_typeof(p_data) is distinct from 'object' or octet_length(p_data::text)>12000 or (p_data-array['title','description','genre','subgenre','moods','bpm','key','releaseYear','instrumental','vocals','explicit'])<>'{}'::jsonb or coalesce(length(p_data->>'title'),0) not between 2 and 160 or coalesce(length(p_data->>'description'),0) not between 20 and 5000 or coalesce(length(p_data->>'genre'),0) not between 1 and 80 or coalesce(length(p_data->>'subgenre'),0) not between 1 and 80 or coalesce(length(p_data->>'moods'),0) not between 1 and 500 or coalesce(length(p_data->>'key'),0) not between 1 and 40 or coalesce(p_data->>'bpm','')!~'^[0-9]{2,3}$' or (p_data->>'bpm')::integer not between 40 and 220 or coalesce(p_data->>'releaseYear','')!~'^[0-9]{4}$' or (p_data->>'releaseYear')::integer not between 1950 and 2030 or jsonb_typeof(p_data->'instrumental') is distinct from 'boolean' or jsonb_typeof(p_data->'vocals') is distinct from 'boolean' or jsonb_typeof(p_data->'explicit') is distinct from 'boolean' or ((p_data->>'instrumental')::boolean and (p_data->>'vocals')::boolean) then raise exception 'Complete the track metadata' using errcode='22023';end if;
 if exists(select 1 from jsonb_each(p_data) e where e.key in ('title','description','genre','subgenre','moods','key') and (jsonb_typeof(e.value) is distinct from 'string' or e.value#>>'{}' is distinct from btrim(e.value#>>'{}'))) then raise exception 'Invalid metadata text' using errcode='22023';end if;
 if s.track_id is null and not exists(select 1 from submission_media.assets where id=s.working_master_id and technical_state='ready') then raise exception 'Validated master required before catalog draft creation' using errcode='22023';end if;
 if s.track_id is null then
  t:=gen_random_uuid();insert into public.tracks(id,artist_user_id,title,slug,description,genre,subgenre,moods,bpm,musical_key,duration_seconds,release_year,instrumental,vocals,explicit,status) values(t,s.owner_id,p_data->>'title','upload-'||t::text,p_data->>'description',p_data->>'genre',p_data->>'subgenre',string_to_array(p_data->>'moods',','),(p_data->>'bpm')::integer,p_data->>'key',(select ceil(duration_us::numeric/1000000)::integer from submission_media.assets where id=s.working_master_id),(p_data->>'releaseYear')::integer,(p_data->>'instrumental')::boolean,(p_data->>'vocals')::boolean,(p_data->>'explicit')::boolean,'draft');update submission_media.submissions set track_id=t where id=s.id;
 else
  t:=s.track_id;perform 1 from public.tracks where id=t and artist_user_id=s.owner_id and status='draft' for update;if not found then raise exception 'Submitted metadata requires the canonical review workflow' using errcode='42501';end if;
  update public.tracks set title=p_data->>'title',description=p_data->>'description',genre=p_data->>'genre',subgenre=p_data->>'subgenre',moods=string_to_array(p_data->>'moods',','),bpm=(p_data->>'bpm')::integer,musical_key=p_data->>'key',release_year=(p_data->>'releaseYear')::integer,instrumental=(p_data->>'instrumental')::boolean,vocals=(p_data->>'vocals')::boolean,explicit=(p_data->>'explicit')::boolean where id=t;
 end if;
 perform submission_media.append_event(s.id,'upload_metadata_saved',null,o.id,null,null,'artist');return submission_media.finish_operation(o.id,jsonb_build_object('track_id',t,'revision',submission_media.bump(s.id)));end$function$

CREATE OR REPLACE FUNCTION public.media_upload_reserve(p_submission uuid, p_role text, p_label text, p_filename text, p_bytes bigint, p_revision bigint, p_key uuid, p_replaces uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions; o submission_media.operations; aid uuid:=gen_random_uuid(); previous submission_media.upload_files; kind text; expires timestamptz:=clock_timestamp()+interval '24 hours'; begin
 perform submission_media.require_capability('reservations');perform pg_advisory_xact_lock(hashtextextended('media-quota:'||submission_media.require_actor('artist')::text,0));s:=submission_media.lock_owned(p_submission,null);
 if p_role is null or p_role not in ('master','instrumental','clean','alternate','stem','supporting','artwork') or p_bytes is null or p_bytes<=0 or p_bytes>(case when p_role='artwork' then 10000000 else 50000000 end) or p_label is null or p_label<>btrim(p_label) or length(p_label) not between 1 and 80 or p_label~'[[:cntrl:]]' or p_filename is null or length(p_filename) not between 1 and 255 or p_filename~'[[:cntrl:]/\\]' then raise exception 'Invalid upload reservation' using errcode='22023';end if;
 if (p_role='artwork' and p_filename !~* '[.](jpg|jpeg|png|webp)$') or (p_role<>'artwork' and p_filename !~* '[.](wav|aif|aiff|aifc|flac)$') then raise exception 'Unsupported upload format' using errcode='22023';end if;
 o:=submission_media.begin_operation(s.id,'reserve_upload',p_key,jsonb_build_object('role',p_role,'label',p_label,'filename',p_filename,'bytes',p_bytes,'revision',p_revision,'replaces',p_replaces));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if exists(select 1 from submission_media.master_reviews where submission_id=s.id and state='pending') then raise exception 'Review in progress' using errcode='55000';end if;
 if p_replaces is not null then select * into previous from submission_media.upload_files where asset_id=p_replaces and submission_id=s.id and retired_at is null and role=p_role and label=p_label for update;if not found then raise exception 'Invalid replacement' using errcode='42501';end if;
 elsif p_role in ('master','artwork') then select * into previous from submission_media.upload_files where submission_id=s.id and role=p_role and retired_at is null for update;
 elsif exists(select 1 from submission_media.upload_files where submission_id=s.id and role=p_role and label=p_label and retired_at is null) then raise exception 'Choose the exact file to replace' using errcode='22023';end if;
 if (select count(*) from submission_media.assets a join submission_media.submissions x on x.id=a.submission_id where x.owner_id=s.owner_id and a.technical_state in ('reserved','uploaded','verifying') and (a.technical_state<>'reserved' or a.reservation_expires_at>now()) and not exists(select 1 from submission_media.upload_files f where f.asset_id=a.id and f.retired_at is not null))>=4 or (select count(*) from submission_media.assets a join submission_media.submissions x on x.id=a.submission_id where x.owner_id=s.owner_id and a.created_at>now()-interval '24 hours' and a.origin='upload')>=20 then raise exception 'Upload limit reached' using errcode='54000';end if;
 kind:=case when p_role='artwork' then 'artwork' else 'source_master' end;
 if previous.asset_id is not null then update submission_media.upload_files set retired_at=clock_timestamp(),retired_reason='replaced' where asset_id=previous.asset_id;end if;
 insert into submission_media.assets(id,submission_id,operation_id,kind,origin,display_filename,declared_bytes,bucket,object_path,reservation_expires_at) values(aid,s.id,o.id,kind,'upload',p_filename,p_bytes,case when kind='artwork' then 'submission-artwork' else 'submission-source' end,s.owner_id::text||'/'||s.id::text||'/'||aid::text||'/original',expires);
 insert into submission_media.upload_files(asset_id,submission_id,role,label) values(aid,s.id,p_role,p_label);
 if p_role='master' then update submission_media.submissions set working_master_id=aid,accepted_preview_id=null,selection_master_id=null,selection_start_ms=null,selection_end_ms=null where id=s.id;end if;
 perform submission_media.append_event(s.id,'asset_reserved',aid,o.id,null,null,'artist',jsonb_build_object('previous_asset_id',previous.asset_id));
 return submission_media.finish_operation(o.id,jsonb_build_object('asset_id',aid,'revision',submission_media.bump(s.id),'expires_at',expires));end$function$

CREATE OR REPLACE FUNCTION public.media_upload_submit(p_submission uuid, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare s submission_media.submissions;o submission_media.operations;r jsonb;prior_status public.track_status;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);o:=submission_media.begin_operation(s.id,'submit_uploads',p_key,jsonb_build_object('revision',p_revision));if o.state='complete' then return o.result;end if;
 if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 if s.track_id is null or s.working_master_id is null or s.accepted_preview_id is null or not exists(select 1 from submission_media.assets where id=s.working_master_id and technical_state='ready') or not exists(select 1 from submission_media.assets where source_asset_id=s.working_master_id and kind='waveform' and technical_state='ready') or exists(select 1 from submission_media.upload_files f join submission_media.assets a on a.id=f.asset_id where f.submission_id=s.id and f.retired_at is null and a.technical_state<>'ready') then raise exception 'Validated Master, waveform, accepted Preview and complete uploads required' using errcode='22023';end if;
 select status into prior_status from public.tracks where id=s.track_id and artist_user_id=s.owner_id for update;
 if prior_status is null or prior_status not in ('draft','pending_review','approved') then raise exception 'Track unavailable for review' using errcode='42501';end if;
 if prior_status<>'approved' then update public.tracks set duration_seconds=(select ceil(duration_us::numeric/1000000)::integer from submission_media.assets where id=s.working_master_id),status='pending_review' where id=s.track_id and artist_user_id=s.owner_id;end if;
 r:=public.media_request_master_review(s.id,s.working_master_id,s.accepted_preview_id,s.revision,gen_random_uuid());return submission_media.finish_operation(o.id,r||jsonb_build_object('track_id',s.track_id,'is_resubmission',prior_status<>'draft'));end$function$

CREATE OR REPLACE FUNCTION public.media_workspace_document_audit(p_document uuid, p_admin boolean, p_outcome text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare d submission_media.workspace_documents;u uuid;begin
 select * into d from submission_media.workspace_documents where id=p_document;if not found then raise exception 'Permission denied' using errcode='42501';end if;
 u:=submission_media.workspace_document_actor(d.submission_id,p_admin);
 if p_outcome is null or p_outcome not in ('authorized','delivered','failed') then raise exception 'Invalid access outcome' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('workspace-document-audit:'||u::text,0));
 if (select count(*) from submission_media.workspace_document_events where actor_id=u and recorded_at>clock_timestamp()-interval '15 minutes')>=300 or (p_outcome='authorized' and (select count(*) from submission_media.workspace_document_events where actor_id=u and action='authorized' and recorded_at>clock_timestamp()-interval '15 minutes')>=30) then raise exception 'Private document access limit' using errcode='54000';end if;
 insert into submission_media.workspace_document_events(document_id,actor_id,action) values(d.id,u,p_outcome);return jsonb_build_object('recorded',true);
end$function$

CREATE OR REPLACE FUNCTION public.media_workspace_document_reserve(p_submission uuid, p_kind text, p_filename text, p_bytes bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions;d submission_media.workspace_documents;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);perform submission_media.workspace_document_editable(s);
 if p_key is null or p_kind is null or p_kind not in ('agreement','authority','sample') or p_filename is null or p_filename!~*'^[^/\\[:cntrl:]]+[.]pdf$' or length(p_filename)>255 or p_bytes is null or p_bytes not between 16 and 3000000 then raise exception 'Invalid private document' using errcode='22023';end if;
 select * into d from submission_media.workspace_documents where owner_id=s.owner_id and reservation_key=p_key;
 if found then
 if d.submission_id<>s.id or d.kind<>p_kind or d.filename<>p_filename or d.bytes<>p_bytes then raise exception 'Idempotency conflict' using errcode='22023';end if;return jsonb_build_object('document_id',d.id);end if;
 if (select count(*) from submission_media.workspace_documents where submission_id=s.id)>=20 then raise exception 'Document reservation limit' using errcode='54000';end if;
 if not exists(select 1 from storage.buckets where id='rights-evidence' and not public and file_size_limit>=p_bytes) then raise exception 'Private evidence storage unavailable' using errcode='55000';end if;
 insert into submission_media.workspace_documents(submission_id,owner_id,kind,filename,bytes,reservation_key) values(s.id,s.owner_id,p_kind,p_filename,p_bytes,p_key) returning * into d;
 insert into submission_media.workspace_document_events(document_id,actor_id,action) values(d.id,s.owner_id,'reserved');return jsonb_build_object('document_id',d.id);
end$function$

CREATE OR REPLACE FUNCTION public.marketplace_set_favorite(p_track uuid, p_value boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare u uuid:=catalog_private.marketplace_buyer();begin
 if p_track is null or p_value is null then raise exception 'Favorite intent required' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('marketplace-favorites:'||u::text,0));
 perform 1 from public.tracks where id=p_track for share;
 if p_value then
  if not catalog_private.visible(p_track) then raise exception 'Track unavailable' using errcode='42501';end if;
  if (select count(*) from public.favorites where buyer_user_id=u)>=10000 and not exists(select 1 from public.favorites where buyer_user_id=u and track_id=p_track) then raise exception 'Favorite limit' using errcode='54000';end if;
  insert into public.favorites(buyer_user_id,track_id) values(u,p_track) on conflict(buyer_user_id,track_id) do nothing;
 else delete from public.favorites where buyer_user_id=u and track_id=p_track;end if;return p_value;
end$function$

CREATE OR REPLACE FUNCTION public.media_processing_status(p_submission uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions; r submission_media.vm_runtime; begin
 perform submission_media.require_capability('reads');s:=submission_media.lock_owned(p_submission,null);
 select * into r from submission_media.vm_runtime where singleton;
 return jsonb_build_object('paused_reason',case when not r.enabled then 'operator_disabled' when r.paused_reason is not null then r.paused_reason when r.observed_at is null or r.observed_at<clock_timestamp()-interval '90 seconds' then 'accounting_stale' end,
 'jobs',(select coalesce(jsonb_agg(jsonb_build_object('id',id,'asset_id',asset_id,'state',state,'attempt',attempt,'retryable',retryable,'dead_letter',state='failed' and not retryable,'error_code',error_code,'available_at',available_at) order by created_at),'[]') from submission_media.jobs where submission_id=s.id));
end $function$

CREATE OR REPLACE FUNCTION submission_media.vm_admit(p_operation uuid, p_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r submission_media.vm_runtime; v submission_media.vm_runs; j submission_media.jobs; a submission_media.assets; n jsonb; run uuid:=p_operation; reservation numeric; bytes bigint; scope submission_media.vm_test_permits; begin
 perform pg_advisory_xact_lock(731003,3);
 select * into r from submission_media.vm_runtime where singleton for update;
 select * into v from submission_media.vm_runs where state='issued' or id=p_operation order by created_at limit 1;
 if found then return jsonb_build_object('state',v.state,'run_id',v.id,'permit_id',v.permit_id,'job_id',v.job_id,'recovery',true);end if;
 if not r.enabled or p_digest is distinct from r.build_digest then return jsonb_build_object('state','operator_disabled'); end if;
 perform submission_media.require_capability('worker');
 if r.month<>to_char(clock_timestamp() at time zone 'UTC','YYYY-MM') or r.observed_at is null or r.observed_at<clock_timestamp()-interval '90 seconds' then return jsonb_build_object('state','accounting_stale'); end if;
 if r.paused_reason is not null then return jsonb_build_object('state',r.paused_reason); end if;
 if submission_media.vm_projection()>=r.pause_usd then update submission_media.vm_runtime set paused_reason='budget_limit' where singleton;insert into submission_media.vm_audit(kind) values('paused');return jsonb_build_object('state','budget_limit');end if;
