CREATE OR REPLACE FUNCTION public.media_accept_asset(p_submission uuid, p_asset uuid, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions; a submission_media.assets; o submission_media.operations; old_id uuid; approved boolean; activate boolean:=false; begin
  perform submission_media.require_capability('reservations'); s:=submission_media.lock_owned(p_submission,null);
  select * into a from submission_media.assets where id=p_asset and submission_id=s.id and kind in ('buyer_preview','artwork') and technical_state='ready' for update;
  if not found then raise exception 'Invalid ready asset' using errcode='42501'; end if;
  o:=submission_media.begin_operation(s.id,case a.kind when 'buyer_preview' then 'accept_preview' else 'accept_artwork' end,p_key,jsonb_build_object('asset',p_asset,'revision',p_revision)); if o.state='complete' then return o.result; end if;
  if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001'; end if;
  if a.kind='buyer_preview' and a.source_asset_id is distinct from s.current_master_id and a.source_asset_id is distinct from s.working_master_id then raise exception 'Stale Preview source' using errcode='22023'; end if;
  if s.track_id is not null then select status='approved' into approved from public.tracks where id=s.track_id and artist_user_id=s.owner_id for update; end if;
  activate:=coalesce(approved,false) and (a.kind='artwork' or (s.managed_master and a.source_asset_id=s.current_master_id));
  if activate then perform submission_media.require_capability('activation'); end if;
  update submission_media.assets set accepted_at=coalesce(accepted_at,clock_timestamp()),accepted_by=coalesce(accepted_by,s.owner_id) where id=a.id;
  if a.kind='buyer_preview' then
    update submission_media.submissions set accepted_preview_id=a.id where id=s.id;
    if activate then old_id:=s.current_preview_id; update submission_media.submissions set current_preview_id=a.id,managed_preview=true where id=s.id; end if;
  else
    update submission_media.submissions set accepted_artwork_id=a.id where id=s.id;
    if activate then old_id:=s.current_artwork_id; update submission_media.submissions set current_artwork_id=a.id,managed_artwork=true where id=s.id; end if;
  end if;
  perform submission_media.append_event(s.id,case a.kind when 'buyer_preview' then 'preview_accepted' else 'artwork_accepted' end,a.id,o.id,null,null,'artist');
  if activate then
    if old_id is distinct from a.id then perform submission_media.supersede(s.id,old_id,o.id); end if;
    perform submission_media.append_event(s.id,'asset_activated',a.id,o.id,null,null,'artist',jsonb_build_object('previous_asset_id',old_id));
  end if;
  return submission_media.finish_operation(o.id,jsonb_build_object('asset_id',a.id,'buyer_active',activate,'revision',submission_media.bump(s.id)));
end $function$

CREATE OR REPLACE FUNCTION public.media_request_master_review(p_submission uuid, p_master uuid, p_preview uuid, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions; o submission_media.operations; h bytea; rid uuid; begin
  perform submission_media.require_capability('reservations'); s:=submission_media.lock_owned(p_submission,null);
  o:=submission_media.begin_operation(s.id,'request_review',p_key,jsonb_build_object('master',p_master,'preview',p_preview,'revision',p_revision)); if o.state='complete' then return o.result; end if;
  if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001'; end if;
  if s.track_id is null or p_master is distinct from s.working_master_id or p_master is not distinct from s.current_master_id or p_preview is distinct from s.accepted_preview_id then raise exception 'Invalid replacement package' using errcode='22023'; end if;
  perform 1 from public.tracks where id=s.track_id and artist_user_id=s.owner_id and status in ('pending_review','approved') for update;
  if not found then raise exception 'Track must enter canonical review workflow first' using errcode='55000'; end if;
  h:=submission_media.package_hash(p_master,p_preview);
  if h is null or not exists(select 1 from submission_media.assets where id=p_master and submission_id=s.id) or not exists(select 1 from submission_media.assets where kind='waveform' and source_asset_id=p_master and submission_id=s.id and technical_state='ready') then raise exception 'New validated Master, waveform and accepted derived Preview required' using errcode='22023'; end if;
  insert into submission_media.master_reviews(submission_id,operation_id,expected_current_master_id,candidate_master_id,candidate_preview_id,package_hash,requested_revision,requested_by)
  values(s.id,o.id,s.current_master_id,p_master,p_preview,h,s.revision+1,s.owner_id) returning id into rid;
  perform submission_media.append_event(s.id,'master_review_requested',p_master,o.id,null,rid,'artist');
  return submission_media.finish_operation(o.id,jsonb_build_object('review_id',rid,'revision',submission_media.bump(s.id)));
end $function$

CREATE OR REPLACE FUNCTION public.media_decide_master_review(p_review uuid, p_approve boolean, p_package_hash text, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=submission_media.require_actor('admin'); r submission_media.master_reviews; s submission_media.submissions; o submission_media.operations; h bytea; begin
  perform submission_media.require_capability('activation');
  select * into r from submission_media.master_reviews where id=p_review;
  if not found then raise exception 'Invalid review' using errcode='42501'; end if;
  select * into s from submission_media.submissions where id=r.submission_id for update;
  perform 1 from public.tracks where id=s.track_id and artist_user_id=s.owner_id and status in ('pending_review','approved') for update;
  if not found then raise exception 'Invalid review track' using errcode='22023'; end if;
  select * into r from submission_media.master_reviews where id=p_review for update;
  o:=submission_media.begin_operation(s.id,'decide_review',p_key,jsonb_build_object('review',p_review,'approve',p_approve,'hash',p_package_hash,'revision',p_revision)); if o.state='complete' then return o.result; end if;
  h:=submission_media.package_hash(r.candidate_master_id,r.candidate_preview_id);
  if p_approve is null or r.state<>'pending' or p_revision is null or s.revision<>p_revision or s.current_master_id is distinct from r.expected_current_master_id or
    p_package_hash is distinct from encode(r.package_hash,'hex') or r.package_hash is distinct from h then raise exception 'Stale review package' using errcode='40001'; end if;
  update submission_media.master_reviews set state=case when p_approve then 'approved' else 'rejected' end,decided_by=u,decided_at=clock_timestamp() where id=r.id;
  if p_approve then
    update submission_media.submissions set current_master_id=r.candidate_master_id,current_preview_id=r.candidate_preview_id,current_review_id=r.id,managed_master=true,managed_preview=true where id=s.id;
    -- Existing moderation guard still enforces rights totals. No rights/certification bypass.
    update public.tracks set status='approved' where id=s.track_id;
    perform submission_media.supersede(s.id,s.current_master_id,o.id);
    perform submission_media.supersede(s.id,s.current_preview_id,o.id);
  end if;
  perform submission_media.append_event(s.id,case when p_approve then 'master_review_approved' else 'master_review_rejected' end,r.candidate_master_id,o.id,null,r.id,'admin');
  return submission_media.finish_operation(o.id,jsonb_build_object('review_id',r.id,'approved',p_approve,'revision',submission_media.bump(s.id)));
end $function$

CREATE OR REPLACE FUNCTION public.media_retry_job(p_submission uuid, p_job uuid, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions; o submission_media.operations; j submission_media.jobs; begin
  perform submission_media.require_capability('reservations'); s:=submission_media.lock_owned(p_submission,null);
  o:=submission_media.begin_operation(s.id,'retry_job',p_key,jsonb_build_object('job',p_job,'revision',p_revision)); if o.state='complete' then return o.result; end if;
  if p_revision is null or s.revision<>p_revision then raise exception 'STALE_REVISION' using errcode='40001'; end if;
  select * into j from submission_media.jobs where id=p_job and submission_id=s.id and state='failed' and retryable and attempt<max_attempts for update;
  if not found then raise exception 'Job cannot retry' using errcode='22023'; end if;
  update submission_media.jobs set state='queued',available_at=clock_timestamp() where id=j.id;
  perform submission_media.append_event(s.id,'job_retried',j.asset_id,o.id,j.id,null,'artist');
  return submission_media.finish_operation(o.id,jsonb_build_object('revision',submission_media.bump(s.id)));
end $function$

CREATE OR REPLACE FUNCTION submission_media.observe_upload(p_asset uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a submission_media.assets; obj storage.objects; s submission_media.submissions; jt text; begin
  perform submission_media.require_capability('reservations');
  select submission_id into s.id from submission_media.assets where id=p_asset;
  select * into s from submission_media.submissions where id=s.id for update;
  select * into a from submission_media.assets where id=p_asset for update;
  if not found or a.origin not in ('upload','legacy_adoption') then raise exception 'Invalid reservation' using errcode='22023'; end if;
  if a.storage_object_id is not null then return jsonb_build_object('asset_id',a.id,'state',a.technical_state); end if;
  if a.reservation_expires_at<=clock_timestamp() then raise exception 'Expired reservation' using errcode='22023'; end if;
  select * into obj from storage.objects where bucket_id=a.bucket and name=a.object_path;
  if not found or obj.version is null or obj.metadata->>'size' is null or (obj.metadata->>'size')::bigint<>a.declared_bytes or
    (a.origin='upload' and coalesce(obj.owner_id,obj.owner::text) is distinct from s.owner_id::text) then raise exception 'Exact object verification failed' using errcode='22023'; end if;
  update submission_media.assets set storage_object_id=obj.id,storage_version=obj.version,storage_bytes=(obj.metadata->>'size')::bigint,
    storage_mime=coalesce(obj.metadata->>'mimetype','application/octet-stream'),technical_state='uploaded',upload_observed_at=clock_timestamp() where id=a.id;
  jt:=case when a.origin='legacy_adoption' then 'legacy_source_verification' when a.kind='source_master' then 'source_validation' else 'artwork_validation' end;
  insert into submission_media.jobs(submission_id,asset_id,operation_id,job_type,profile_version)
  values(a.submission_id,a.id,a.operation_id,jt,case when a.kind='source_master' then 'source-validator-v1' else 'artwork-validator-v1' end) on conflict do nothing;
  perform submission_media.append_event(a.submission_id,'upload_observed',a.id,a.operation_id,null,null,'worker');
  perform submission_media.bump(s.id);
  return jsonb_build_object('asset_id',a.id,'state','uploaded');
end $function$

CREATE OR REPLACE FUNCTION submission_media.claim_job()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j submission_media.jobs; a submission_media.assets; m submission_media.assets; exhausted submission_media.jobs; begin
  perform submission_media.require_capability('worker');
  -- Serialize the short claim transaction; processing remains concurrent across owners.
  perform pg_catalog.pg_advisory_xact_lock(731003,1);
  -- Exhausted abandoned leases become visible failures instead of silently stuck jobs.
  for exhausted in update submission_media.jobs set state='failed',lease_token=null,lease_expires_at=null,error_code='worker_lease_expired',retryable=false,completed_at=clock_timestamp()
    where state='running' and lease_expires_at<clock_timestamp() and attempt>=max_attempts returning * loop
    update submission_media.assets set technical_state='failed',safe_error_code='TEMPORARY_SYSTEM_ERROR' where id=exhausted.asset_id and technical_state='verifying';
    perform submission_media.append_event(exhausted.submission_id,'validation_failed',exhausted.asset_id,exhausted.operation_id,exhausted.id,null,'worker',jsonb_build_object('error_code','TEMPORARY_SYSTEM_ERROR'));
  end loop;
  select * into j from submission_media.jobs where attempt<max_attempts and
    ((state in ('queued','retry_wait') and available_at<=clock_timestamp()) or (state='running' and lease_expires_at<clock_timestamp()))
    and not exists(select 1 from submission_media.jobs running join submission_media.submissions rs on rs.id=running.submission_id join submission_media.submissions cs on cs.id=jobs.submission_id where rs.owner_id=cs.owner_id and running.id<>jobs.id and running.state='running')
    order by available_at,id for update skip locked limit 1;
  if not found then return null; end if;
  update submission_media.jobs set state='running',attempt=attempt+1,lease_epoch=lease_epoch+1,lease_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '5 minutes',
    started_at=coalesce(started_at,clock_timestamp()),heartbeat_at=clock_timestamp() where id=j.id returning * into j;
  select * into a from submission_media.assets where id=j.asset_id;
  if a.technical_state<>'ready' then update submission_media.assets set technical_state='verifying',safe_error_code=null,reservation_expires_at=case when origin='generated' then clock_timestamp()+interval '24 hours' else reservation_expires_at end where id=a.id; end if;
  if a.source_asset_id is not null then select * into m from submission_media.assets where id=a.source_asset_id; end if;
  perform submission_media.append_event(j.submission_id,'validation_started',a.id,j.operation_id,j.id,null,'worker',jsonb_build_object('lease_epoch',j.lease_epoch,'attempt',j.attempt));
  return jsonb_build_object('job_id',j.id,'lease_epoch',j.lease_epoch,'lease_token',j.lease_token,'job_type',j.job_type,'profile',j.profile_version,
    'asset_id',a.id,'bucket',a.bucket,'path',a.object_path,'object_id',a.storage_object_id,'version',a.storage_version,
    'source',case when m.id is null then null else jsonb_build_object('asset_id',m.id,'bucket',m.bucket,'path',m.object_path,'object_id',m.storage_object_id,'version',m.storage_version,'sha256',encode(m.sha256,'hex'),'sample_rate',m.sample_rate,'frames',m.measured_frames) end,
    'start_sample',a.start_sample,'end_sample',a.end_sample);
end $function$

CREATE OR REPLACE FUNCTION submission_media.complete_job(p_job uuid, p_epoch bigint, p_token uuid, p_result jsonb, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j submission_media.jobs; a submission_media.assets; obj storage.objects; s submission_media.submissions; w uuid; code text; begin
  perform submission_media.require_capability('worker');
  select * into j from submission_media.jobs where id=p_job;
  if not found then raise exception 'Invalid job' using errcode='42501'; end if;
  select * into s from submission_media.submissions where id=j.submission_id for update;
  select * into j from submission_media.jobs where id=p_job for update;
  if j.state<>'running' or p_epoch is null or p_token is null or j.lease_epoch<>p_epoch or j.lease_token<>p_token or j.lease_expires_at<=clock_timestamp() then raise exception 'Stale worker lease' using errcode='40001'; end if;
  select * into a from submission_media.assets where id=j.asset_id for update;
  if p_error is not null then
    code:=case p_error when 'unsupported_format' then 'UNSUPPORTED_FORMAT' when 'file_too_large' then 'FILE_TOO_LARGE' when 'audio_unreadable' then 'AUDIO_UNREADABLE'
      when 'no_audio_frames' then 'NO_AUDIO_FRAMES' when 'unsupported_audio_configuration' then 'UNSUPPORTED_AUDIO_CONFIGURATION' when 'waveform_generation_failed' then 'WAVEFORM_GENERATION_FAILED'
      when 'preview_generation_failed' then 'PREVIEW_GENERATION_FAILED' when 'artwork_invalid' then 'ARTWORK_INVALID' else 'TEMPORARY_SYSTEM_ERROR' end;
    update submission_media.jobs set state=case when p_error in ('validator_timeout','temporary_system_error') and attempt<max_attempts then 'retry_wait' else 'failed' end,
      retryable=p_error in ('validator_timeout','temporary_system_error'),error_code=p_error,lease_token=null,lease_expires_at=null,available_at=clock_timestamp()+interval '30 seconds',completed_at=clock_timestamp() where id=j.id;
    update submission_media.assets set technical_state='failed',safe_error_code=code where id=a.id;
    perform submission_media.append_event(s.id,'validation_failed',a.id,j.operation_id,j.id,null,'worker',jsonb_build_object('error_code',code));
    perform submission_media.bump(s.id);
    return jsonb_build_object('state','failed','error_code',code);
  end if;
  if jsonb_typeof(p_result) is distinct from 'object' or octet_length(p_result::text)>4096 or exists(select 1 from jsonb_object_keys(p_result) k where k not in
    ('sha256','actual_bytes','container','codec','frames','duration_us','sample_rate','channels','bit_depth','width','height','animated','waveform_points','build_digest','source_sha256')) or
    (p_result->>'sha256') !~ '^[a-f0-9]{64}$' or (p_result->>'build_digest') !~ '^sha256:[a-f0-9]{64}$' then raise exception 'Invalid bounded validator result' using errcode='22023'; end if;
  select * into obj from storage.objects where bucket_id=a.bucket and name=a.object_path;
  if not found or obj.version is null or (a.storage_object_id is not null and (obj.id,obj.version) is distinct from (a.storage_object_id,a.storage_version)) or
    obj.metadata->>'size' is null or (obj.metadata->>'size')::bigint is distinct from (p_result->>'actual_bytes')::bigint then raise exception 'Storage identity mismatch' using errcode='22023'; end if;
  if a.source_asset_id is not null and not exists(select 1 from submission_media.assets m where m.id=a.source_asset_id and m.technical_state='ready' and encode(m.sha256,'hex')=p_result->>'source_sha256') then raise exception 'Source checksum mismatch' using errcode='22023'; end if;
  if a.kind='artwork' and (p_result->>'animated')::boolean is distinct from false then raise exception 'Artwork invalid' using errcode='22023'; end if;
  if a.kind='buyer_preview' and abs((p_result->>'duration_us')::bigint-(a.region_end_ms-a.region_start_ms)*1000)>100000 then raise exception 'Preview duration mismatch' using errcode='22023'; end if;
  if a.kind='waveform' and (p_result->>'waveform_points')::integer is distinct from (select ceil(duration_us::numeric/10000)::integer from submission_media.assets where id=a.source_asset_id) then raise exception 'Waveform resolution mismatch' using errcode='22023'; end if;
  update submission_media.assets set technical_state='ready',storage_object_id=obj.id,storage_version=obj.version,storage_bytes=(p_result->>'actual_bytes')::bigint,storage_mime=coalesce(obj.metadata->>'mimetype','application/octet-stream'),
    sha256=decode(p_result->>'sha256','hex'),container=p_result->>'container',codec=p_result->>'codec',measured_frames=(p_result->>'frames')::bigint,duration_us=(p_result->>'duration_us')::bigint,
    sample_rate=(p_result->>'sample_rate')::integer,channels=(p_result->>'channels')::integer,bit_depth=(p_result->>'bit_depth')::integer,image_width=(p_result->>'width')::integer,image_height=(p_result->>'height')::integer,
    waveform_points=(p_result->>'waveform_points')::integer,worker_build_digest=p_result->>'build_digest',validator_version=j.profile_version,verified_at=clock_timestamp(),safe_error_code=null where id=a.id;
  update submission_media.jobs set state='succeeded',lease_token=null,lease_expires_at=null,completed_at=clock_timestamp(),retryable=false,error_code=null where id=j.id;
  perform submission_media.append_event(s.id,case a.kind when 'waveform' then 'waveform_generated' when 'buyer_preview' then 'preview_generated' else 'validation_passed' end,a.id,j.operation_id,j.id,null,'worker');
  if a.kind='source_master' then
    w:=gen_random_uuid();
    insert into submission_media.assets(id,submission_id,operation_id,kind,origin,bucket,object_path,reservation_expires_at,source_asset_id,generation_profile)
      values(w,s.id,j.operation_id,'waveform','generated','submission-derived',s.owner_id::text||'/'||s.id::text||'/'||w::text||'/waveform.bin',clock_timestamp()+interval '24 hours',a.id,'waveform-minmax-v1');
    insert into submission_media.jobs(submission_id,asset_id,operation_id,job_type,profile_version) values(s.id,w,j.operation_id,'waveform_generation','waveform-minmax-v1');
  end if;
  return jsonb_build_object('asset_id',a.id,'state','ready','revision',submission_media.bump(s.id));
end $function$

CREATE OR REPLACE FUNCTION submission_media.guard_storage_object()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a submission_media.assets; relevant boolean; begin
  relevant:=case when tg_op='DELETE' then old.bucket_id in ('submission-source','submission-artwork','submission-derived')
    when tg_op='UPDATE' then old.bucket_id in ('submission-source','submission-artwork','submission-derived') or new.bucket_id in ('submission-source','submission-artwork','submission-derived')
    else new.bucket_id in ('submission-source','submission-artwork','submission-derived') end;
  -- Also seal explicitly adopted legacy sources without affecting other legacy objects.
  if not relevant then
    if tg_op<>'INSERT' then select * into a from submission_media.assets where bucket=old.bucket_id and object_path=old.name and origin='legacy_adoption'; end if;
    if a.id is null then if tg_op='DELETE' then return old; else return new; end if; end if;
  end if;
  if tg_op='DELETE' then raise exception 'Submission media is retained' using errcode='42501'; end if;
  if tg_op='UPDATE' then
    if (new.id,new.bucket_id,new.name,new.version,new.owner,new.owner_id,new.metadata->'size',new.metadata->'mimetype') is distinct from
      (old.id,old.bucket_id,old.name,old.version,old.owner,old.owner_id,old.metadata->'size',old.metadata->'mimetype') then
      raise exception 'Immutable submission Storage object' using errcode='42501';
    end if;
    return new;
  end if;
  select * into a from submission_media.assets where bucket=new.bucket_id and object_path=new.name for update;
  if not found or a.technical_state not in ('reserved','verifying') or a.storage_object_id is not null or a.reservation_expires_at<=clock_timestamp() then
    raise exception 'Exact live reservation required' using errcode='42501';
  end if;
  if a.origin='upload' then
    if not exists(select 1 from submission_media.capabilities where singleton and reservations_enabled) or
      coalesce(new.owner_id,new.owner::text) is distinct from (select owner_id::text from submission_media.submissions where id=a.submission_id) then
      raise exception 'Reservation owner mismatch' using errcode='42501'; end if;
  elsif a.origin='generated' then
    if not exists(select 1 from submission_media.capabilities where singleton and worker_enabled) or not exists
      (select 1 from submission_media.jobs where asset_id=a.id and state='running' and lease_expires_at>clock_timestamp()) then
      raise exception 'Assigned live derivative job required' using errcode='42501'; end if;
  else raise exception 'Legacy object cannot be recreated' using errcode='42501'; end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION submission_media.resolve_worker_io(p_job uuid, p_epoch bigint, p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j submission_media.jobs; a submission_media.assets; m submission_media.assets; o storage.objects; src storage.objects; begin
  perform submission_media.require_capability('worker');
  select * into j from submission_media.jobs where id=p_job for update;
  if not found or j.state<>'running' or p_epoch is null or p_token is null or j.lease_epoch<>p_epoch
    or j.lease_token<>p_token or j.lease_expires_at<=clock_timestamp() then
    raise exception 'Stale worker lease' using errcode='40001';
  end if;
  select * into a from submission_media.assets where id=j.asset_id;
  if a.submission_id<>j.submission_id or a.technical_state<>'verifying' or a.kind<>(case j.job_type
    when 'source_validation' then 'source_master' when 'legacy_source_verification' then 'source_master'
    when 'artwork_validation' then 'artwork' when 'waveform_generation' then 'waveform' when 'preview_generation' then 'buyer_preview' else '' end) or
    j.profile_version<>(case j.job_type when 'source_validation' then 'source-validator-v1'
    when 'legacy_source_verification' then 'source-validator-v1' when 'artwork_validation' then 'artwork-validator-v1'
    when 'waveform_generation' then 'waveform-minmax-v1' when 'preview_generation' then 'preview-aac-lc-v1' else '' end) then
    raise exception 'Invalid trusted job' using errcode='42501';
  end if;
  if j.job_type in ('source_validation','legacy_source_verification','artwork_validation') then
    select * into o from storage.objects where id=a.storage_object_id and version=a.storage_version
      and bucket_id=a.bucket and name=a.object_path;
    if not found or (o.metadata->>'size')::bigint is distinct from a.storage_bytes then
      raise exception 'Storage identity mismatch' using errcode='22023';
    end if;
  else
    select * into m from submission_media.assets where id=a.source_asset_id and submission_id=a.submission_id
      and kind='source_master' and technical_state='ready';
    if not found or a.generation_profile<>j.profile_version or a.bucket<>'submission-derived' then
      raise exception 'Invalid source provenance' using errcode='42501';
    end if;
    select * into src from storage.objects where id=m.storage_object_id and version=m.storage_version
      and bucket_id=m.bucket and name=m.object_path;
    if not found or (src.metadata->>'size')::bigint is distinct from m.storage_bytes then
      raise exception 'Storage identity mismatch' using errcode='22023';
    end if;
  end if;
  return jsonb_build_object('job_id',j.id,'asset_id',a.id,'operation_id',j.operation_id,'submission_id',a.submission_id,
    'lease_epoch',j.lease_epoch,'lease_token',j.lease_token,'job_type',j.job_type,'profile',j.profile_version,
    'bucket',a.bucket,'path',a.object_path,'object_id',a.storage_object_id,'version',a.storage_version,
    'bytes',a.storage_bytes,'sha256',encode(a.sha256,'hex'),
    'max_bytes',case a.kind when 'waveform' then 2000000 when 'buyer_preview' then 4000000 when 'artwork' then 10000000 else 250000000 end,
    'region_start_ms',a.region_start_ms,'region_end_ms',a.region_end_ms,'start_sample',a.start_sample,'end_sample',a.end_sample,
    'output',case when j.output_object_id is null then null else jsonb_build_object('object_id',j.output_object_id,'version',j.output_version,
      'sha256',encode(j.output_sha256,'hex'),'bytes',j.output_bytes,'lease_epoch',j.output_lease_epoch) end,
    'source',case when m.id is null then null else jsonb_build_object('asset_id',m.id,'object_id',m.storage_object_id,
      'version',m.storage_version,'bucket',m.bucket,'path',m.object_path,'bytes',m.storage_bytes,'sha256',encode(m.sha256,'hex'),
      'container',m.container,'codec',m.codec,'frames',m.measured_frames,'duration_us',m.duration_us,'sample_rate',m.sample_rate,'channels',m.channels,'bit_depth',m.bit_depth) end);
end $function$

CREATE OR REPLACE FUNCTION submission_media.record_worker_output(p_job uuid, p_epoch bigint, p_token uuid, p_object uuid, p_version text, p_sha256 text, p_bytes bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare facts jsonb; j submission_media.jobs; obj storage.objects; begin
  facts:=submission_media.resolve_worker_io(p_job,p_epoch,p_token);
  if facts->>'job_type' not in ('waveform_generation','preview_generation') or p_sha256 is null or p_sha256 !~ '^[a-f0-9]{64}$'
    or p_bytes is null or p_bytes<1 or p_bytes>(facts->>'max_bytes')::bigint then
    raise exception 'Invalid bounded output evidence' using errcode='22023';
  end if;
  select * into obj from storage.objects where id=p_object and version=p_version
    and bucket_id=facts->>'bucket' and name=facts->>'path';
  if not found or (obj.metadata->>'size')::bigint is distinct from p_bytes then
    raise exception 'Storage identity mismatch' using errcode='22023';
  end if;
  select * into j from submission_media.jobs where id=p_job;
  if j.output_object_id is not null and (j.output_object_id,j.output_version,j.output_sha256,j.output_bytes)
    is distinct from (p_object,p_version,decode(p_sha256,'hex'),p_bytes) then
    raise exception 'Immutable derivative evidence' using errcode='42501';
  end if;
  update submission_media.jobs set output_object_id=p_object,output_version=p_version,output_sha256=decode(p_sha256,'hex'),
    output_bytes=p_bytes,output_lease_epoch=p_epoch where id=p_job;
end $function$

CREATE OR REPLACE FUNCTION submission_media.claim_targeted_job(p_permit uuid, p_execution text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p submission_media.execution_permits; j submission_media.jobs; s submission_media.submissions; begin
 perform submission_media.require_capability('worker');
 perform pg_catalog.pg_advisory_xact_lock(731003,1);
 select * into p from submission_media.execution_permits where id=p_permit for update;
 if not found or p.expires_at<=clock_timestamp() or p.execution_name is distinct from p_execution then raise exception 'PERMIT_INVALID' using errcode='42501'; end if;
 if p.state='claimed' then return submission_media.resolve_worker_io(p.job_id,p.lease_epoch,p.lease_token); end if;
 if p.state<>'requested' then raise exception 'PERMIT_INVALID' using errcode='42501'; end if;
 select * into j from submission_media.jobs where id=p.job_id for update;
 select * into s from submission_media.submissions where id=j.submission_id;
 if not found or (j.asset_id,j.job_type,j.profile_version,j.state,j.attempt) is distinct from (p.asset_id,p.job_type,p.profile,p.expected_state,p.expected_attempt) or j.attempt>=j.max_attempts or
 not ((j.state in ('queued','retry_wait') and j.available_at<=clock_timestamp()) or (j.state='running' and j.lease_expires_at<=clock_timestamp())) or
 exists(select 1 from submission_media.jobs r join submission_media.submissions rs on rs.id=r.submission_id where rs.owner_id=s.owner_id and r.id<>j.id and r.state='running') then raise exception 'JOB_NOT_ELIGIBLE' using errcode='40001'; end if;
 update submission_media.jobs set state='running',attempt=attempt+1,lease_epoch=lease_epoch+1,lease_token=gen_random_uuid(),lease_expires_at=clock_timestamp()+interval '5 minutes',started_at=coalesce(started_at,clock_timestamp()),heartbeat_at=clock_timestamp() where id=j.id returning * into j;
 update submission_media.assets set technical_state='verifying',safe_error_code=null,reservation_expires_at=case when origin='generated' then clock_timestamp()+interval '24 hours' else reservation_expires_at end where id=j.asset_id;
 update submission_media.execution_permits set state='claimed',consumed_at=clock_timestamp(),lease_epoch=j.lease_epoch,lease_token=j.lease_token where id=p.id;
 perform submission_media.append_event(j.submission_id,'validation_started',j.asset_id,j.operation_id,j.id,null,'worker',jsonb_build_object('lease_epoch',j.lease_epoch,'attempt',j.attempt));
 return submission_media.resolve_worker_io(j.id,j.lease_epoch,j.lease_token);
end $function$

CREATE OR REPLACE FUNCTION submission_media.complete_execution(p_permit uuid, p_execution text, p_job uuid, p_epoch bigint, p_token uuid, p_result jsonb, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; p submission_media.execution_permits; begin
 select * into p from submission_media.execution_permits where id=p_permit for update;
 if p.state in ('completed','failed') and (p.execution_name,p.job_id,p.lease_epoch,p.lease_token) is not distinct from (p_execution,p_job,p_epoch,p_token) then
 if p.completion_hash is distinct from extensions.digest(coalesce(p_result::text,'')||coalesce(p_error,''),'sha256') then raise exception 'PERMIT_INVALID' using errcode='22023'; end if;
 return p.outcome; end if;
 perform submission_media.resolve_execution_lease(p_permit,p_execution,p_job,p_epoch,p_token);
 result:=submission_media.complete_job(p_job,p_epoch,p_token,p_result,p_error);
 update submission_media.execution_permits set state=case when p_error is null then 'completed' else 'failed' end,outcome=result,completion_hash=extensions.digest(coalesce(p_result::text,'')||coalesce(p_error,''),'sha256') where id=p_permit;
 return result;
end $function$

CREATE OR REPLACE FUNCTION submission_media.create_execution_permit(p_job uuid, p_asset uuid, p_type text, p_profile text, p_state text, p_attempt integer, p_correlation uuid, p_dispatcher text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j submission_media.jobs; p submission_media.execution_permits; begin
 perform pg_catalog.pg_advisory_xact_lock(731003,2);
 select * into p from submission_media.execution_permits where correlation_id=p_correlation;
 if found then
  if (p.job_id,p.asset_id,p.job_type,p.profile,p.expected_state,p.expected_attempt,p.dispatcher_subject) is distinct from (p_job,p_asset,p_type,p_profile,p_state,p_attempt,p_dispatcher) then raise exception 'PERMIT_INVALID' using errcode='22023'; end if;
  return jsonb_build_object('permit_id',p.id,'state',p.state);
 end if;
 update submission_media.execution_permits set state='expired' where state in ('created','requested','claimed') and expires_at<=clock_timestamp();
 select * into j from submission_media.jobs where id=p_job for update;
 if not found or (j.asset_id,j.job_type,j.profile_version,j.state,j.attempt) is distinct from (p_asset,p_type,p_profile,p_state,p_attempt) or j.attempt>=j.max_attempts or
 not ((j.state in ('queued','retry_wait') and j.available_at<=clock_timestamp()) or (j.state='running' and j.lease_expires_at<=clock_timestamp())) then
 raise exception 'JOB_NOT_ELIGIBLE' using errcode='40001'; end if;
 insert into submission_media.execution_permits(correlation_id,job_id,asset_id,job_type,profile,expected_state,expected_attempt,dispatcher_subject)
 values(p_correlation,p_job,p_asset,p_type,p_profile,p_state,p_attempt,p_dispatcher) returning * into p;
 return jsonb_build_object('permit_id',p.id,'state',p.state);
end $function$

CREATE OR REPLACE FUNCTION submission_media.inspect_worker_output(p_job uuid, p_epoch bigint, p_token uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare facts jsonb; o storage.objects; begin
 facts:=submission_media.resolve_worker_io(p_job,p_epoch,p_token);
 if facts->>'job_type' not in ('waveform_generation','preview_generation') then raise exception 'OUTPUT_PROVENANCE_MISMATCH' using errcode='42501'; end if;
 select * into o from storage.objects where bucket_id=facts->>'bucket' and name=facts->>'path';
 if not found then return null; end if;
 return jsonb_build_object('object_id',o.id,'version',o.version,'bytes',(o.metadata->>'size')::bigint,'bucket',o.bucket_id,'path',o.name);
end $function$

CREATE OR REPLACE FUNCTION submission_media.request_execution(p_permit uuid, p_dispatcher text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p submission_media.execution_permits; fresh boolean; begin
 select * into p from submission_media.execution_permits where id=p_permit for update;
 if not found or p.dispatcher_subject<>p_dispatcher or p.expires_at<=clock_timestamp() or p.state not in ('created','requested','claimed','completed','failed') then raise exception 'PERMIT_INVALID' using errcode='42501'; end if;
 fresh:=p.state='created';
 if fresh then update submission_media.execution_permits set state='requested',requested_at=clock_timestamp() where id=p.id; end if;
 return jsonb_build_object('invoke',fresh,'state',case when fresh then 'requested' else p.state end,'execution_name',p.execution_name);
end $function$

CREATE OR REPLACE FUNCTION submission_media.validate_workspace_rights(p_submission uuid, d jsonb, p_complete boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare a jsonb;s jsonb;g jsonb;c jsonb;keys text[]:=array['publishingOwners','authority','hasSamples','samples','hasClaims','claims','hasAgreements','agreements'];begin
 if not d ?| keys and not p_complete then return;end if;
 if not d ?& keys then raise exception 'Structured rights information required' using errcode='22023';end if;
 perform submission_media.validate_master_owners(d->'publishingOwners',p_complete);
 if jsonb_typeof(d->'hasSamples') is distinct from 'boolean' or jsonb_typeof(d->'hasClaims') is distinct from 'boolean' or jsonb_typeof(d->'hasAgreements') is distinct from 'boolean' or jsonb_typeof(d->'samples') is distinct from 'array' or jsonb_typeof(d->'claims') is distinct from 'array' or jsonb_typeof(d->'agreements') is distinct from 'array' then raise exception 'Invalid disclosure classifications' using errcode='22023';end if;
 if jsonb_array_length(d->'samples')>10 or jsonb_array_length(d->'claims')>10 or jsonb_array_length(d->'agreements')>10 then raise exception 'Disclosure limit' using errcode='22023';end if;
 a:=d->'authority';
 perform submission_media.workspace_text_object(a,'{"mode": 20, "legalName": 200, "company": 200, "capacity": 100, "email": 254, "jurisdiction": 100, "address": 500, "representedOwners": 1000, "rights": 20, "uses": 1000, "territories": 500, "validFrom": 10, "validUntil": 10, "exclusivity": 20, "restrictions": 2000, "documentId": 36}'::jsonb);
 if a->>'mode' not in ('unknown','owners','representative') or a->>'rights' not in ('unknown','master','publishing','both') or a->>'exclusivity' not in ('unknown','nonexclusive','exclusive','both') then raise exception 'Invalid authority classification' using errcode='22023';end if;
 perform submission_media.workspace_document_ref(p_submission,a->>'documentId','authority');
 if p_complete and (a->>'mode'='unknown' or (a->>'mode'='representative' and (btrim(a->>'legalName')='' or btrim(a->>'capacity')='' or btrim(a->>'jurisdiction')='' or btrim(a->>'address')='' or a->>'email'!~'^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or btrim(a->>'representedOwners')='' or a->>'rights'='unknown' or btrim(a->>'uses')='' or btrim(a->>'territories')='' or not submission_media.workspace_date_window(a->>'validFrom',a->>'validUntil') or a->>'exclusivity'='unknown' or a->>'documentId'=''))) then raise exception 'Complete licensing authority required' using errcode='22023';end if;
 if p_complete and ((d->>'hasSamples')::boolean is distinct from (jsonb_array_length(d->'samples')>0) or (d->>'hasClaims')::boolean is distinct from (jsonb_array_length(d->'claims')>0) or (d->>'hasAgreements')::boolean is distinct from (jsonb_array_length(d->'agreements')>0)) then raise exception 'Review retained disclosures' using errcode='22023';end if;
 for s in select value from jsonb_array_elements(d->'samples') loop
 perform submission_media.workspace_text_object(s,'{"title": 200, "artist": 200, "identifier": 100, "use": 20, "masterOwner": 200, "publisher": 200, "sourceStart": 10, "sourceEnd": 10, "trackStart": 10, "trackEnd": 10, "description": 1000, "clearance": 20, "documentId": 36}'::jsonb);
 if s->>'use' not in ('unknown','recording','interpolation') or s->>'clearance' not in ('unknown','pending','claimed_cleared') then raise exception 'Invalid sample classification' using errcode='22023';end if;
 perform submission_media.workspace_document_ref(p_submission,s->>'documentId','sample');
 if p_complete and (btrim(s->>'title')='' or btrim(s->>'artist')='' or s->>'use'='unknown' or (s->>'use'='recording' and btrim(s->>'masterOwner')='') or btrim(s->>'publisher')='' or not submission_media.workspace_region(s->>'sourceStart',s->>'sourceEnd') or not submission_media.workspace_region(s->>'trackStart',s->>'trackEnd') or btrim(s->>'description')='' or s->>'clearance'='unknown' or (s->>'clearance'='claimed_cleared' and s->>'documentId'='')) then raise exception 'Complete sample disclosure required' using errcode='22023';end if;
 end loop;
 for c in select value from jsonb_array_elements(d->'claims') loop
 perform submission_media.workspace_text_object(c,'{"claimant": 200, "kind": 20, "reference": 200, "details": 2000, "status": 20, "resolution": 1000}'::jsonb);
 if c->>'kind' not in ('unknown','ownership','copyright','exclusivity','other') or c->>'status' not in ('unknown','open','claimed_resolved') then raise exception 'Invalid claim classification' using errcode='22023';end if;
 if p_complete and (btrim(c->>'claimant')='' or c->>'kind'='unknown' or btrim(c->>'details')='' or c->>'status'='unknown' or (c->>'status'='claimed_resolved' and btrim(c->>'resolution')='')) then raise exception 'Complete claim disclosure required' using errcode='22023';end if;
 end loop;
 for g in select value from jsonb_array_elements(d->'agreements') loop
 perform submission_media.workspace_text_object(g,'{"title": 200, "counterparty": 200, "kind": 30, "rights": 20, "validFrom": 10, "validUntil": 10, "territories": 500, "restrictions": 2000, "documentId": 36}'::jsonb);
 if g->>'kind' not in ('unknown','publishing','label','distribution','administration','exclusive_license','other') or g->>'rights' not in ('unknown','master','publishing','both') then raise exception 'Invalid agreement classification' using errcode='22023';end if;
 perform submission_media.workspace_document_ref(p_submission,g->>'documentId','agreement');
 if p_complete and (btrim(g->>'title')='' or btrim(g->>'counterparty')='' or g->>'kind'='unknown' or g->>'rights'='unknown' or not submission_media.workspace_date_window(g->>'validFrom',g->>'validUntil') or btrim(g->>'territories')='' or g->>'documentId'='') then raise exception 'Complete existing agreement and document required' using errcode='22023';end if;
 end loop;
end$function$

CREATE OR REPLACE FUNCTION submission_media.workspace_document_actor(p_submission uuid, p_admin boolean)
