CREATE OR REPLACE FUNCTION submission_media.vm_test_authorize(p_id uuid, p_artist uuid, p_submission uuid, p_source uuid, p_object uuid, p_version text, p_sha text, p_stages jsonb, p_until timestamp with time zone, p_approval text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare a submission_media.assets;r submission_media.vm_runtime;issued timestamptz:=clock_timestamp();old uuid;begin
 if current_user<>'postgres' then raise exception 'Verified installer required';end if;
 perform pg_advisory_xact_lock(731003,3);
 select permit_id into old from submission_media.vm_test_gate where singleton for update;
 if exists(select 1 from submission_media.vm_runs where state='issued') or
 exists(select 1 from submission_media.vm_test_permits where id=old and expires_at>issued and not exists(select 1 from submission_media.vm_test_revocations where permit_id=old)) then raise exception 'Existing acceptance authority must be settled/revoked';end if;
 if p_id is null or p_artist is null or p_submission is null or p_source is null or p_object is null or p_version is null or p_sha is null or p_sha!~'^[a-f0-9]{64}$' or p_approval is null or p_approval!~'^[a-f0-9]{64}$' or p_until is null or p_until<=issued or p_until>issued+interval '2 hours' or
 p_stages is null or jsonb_typeof(p_stages)<>'array' or jsonb_array_length(p_stages) not between 1 and 3 or not(p_stages <@ '["source_validation","waveform_generation","preview_generation"]'::jsonb) or
 (select count(*) from jsonb_array_elements(p_stages))<>(select count(distinct value) from jsonb_array_elements(p_stages)) then raise exception 'Invalid exact synthetic permit';end if;
 select * into r from submission_media.vm_runtime where singleton;
 if r.build_digest is null then raise exception 'Approved image binding required';end if;
 select * into a from submission_media.assets where id=p_source and submission_id=p_submission;
 if not found or a.storage_object_id is distinct from p_object or a.storage_version is distinct from p_version then raise exception 'Exact source identity required';end if;
 insert into submission_media.vm_test_permits(id,artist_id,submission_id,source_asset_id,object_id,storage_version,bucket,object_path,source_bytes,source_sha256,stages,build_digest,authorization_sha256,issued_at,expires_at)
 values(p_id,p_artist,p_submission,p_source,p_object,p_version,a.bucket,a.object_path,a.storage_bytes,p_sha,p_stages,r.build_digest,p_approval,issued,p_until);
 update submission_media.vm_test_gate set permit_id=p_id where singleton;
 if not exists(select 1 from submission_media.jobs j where j.asset_id=p_source and j.job_type='source_validation' and submission_media.vm_test_valid(p_id,j.id)) then raise exception 'Canonical authorized synthetic source required';end if;
 return p_id;
end $function$

CREATE OR REPLACE FUNCTION submission_media.vm_test_revoke(p_permit uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if current_user<>'postgres' then raise exception 'Verified installer required';end if;
 -- Only short claim/record/finish statements hold the corresponding shared lock;
 -- no shared scope lock is held across external Storage/network transfers.
 perform pg_advisory_xact_lock(hashtextextended('vm-test:'||p_permit::text,0));
 insert into submission_media.vm_test_revocations(permit_id,reason) values(p_permit,p_reason) on conflict(permit_id) do nothing;
end $function$

CREATE OR REPLACE FUNCTION submission_media.vm_test_require(p_run uuid, p_commit boolean DEFAULT false)
 RETURNS submission_media.vm_test_permits
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v submission_media.vm_runs;p submission_media.vm_test_permits;begin
 if p_commit then select * into v from submission_media.vm_runs where id=p_run for update;else select * into v from submission_media.vm_runs where id=p_run;end if;
 if p_commit and v.test_permit_id is not null then perform pg_advisory_xact_lock_shared(hashtextextended('vm-test:'||v.test_permit_id::text,0));end if;
 select * into p from submission_media.vm_test_permits where id=v.test_permit_id and build_digest=v.build_digest;
 if not found or not exists(select 1 from submission_media.vm_runtime where singleton and build_digest=p.build_digest) or not submission_media.vm_test_valid(p.id,v.job_id) or not exists(select 1 from submission_media.vm_test_jobs where permit_id=p.id and job_id=v.job_id) then raise exception 'Synthetic processing authorization unavailable' using errcode='42501';end if;
 return p;
end $function$

CREATE OR REPLACE FUNCTION submission_media.vm_scope_status(p_run uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v submission_media.vm_runs;p submission_media.vm_test_permits;ok boolean:=false;begin
 select * into v from submission_media.vm_runs where state='issued' and (p_run is null or id=p_run);
 if not found then return jsonb_build_object('state','none','authorized',false);end if;
 begin p:=submission_media.vm_test_require(v.id);ok:=exists(select 1 from submission_media.vm_runtime where singleton and enabled and paused_reason is null and build_digest=v.build_digest and observed_at>clock_timestamp()-interval '90 seconds' and month=to_char(clock_timestamp() at time zone 'UTC','YYYY-MM')) and exists(select 1 from submission_media.capabilities where worker_enabled);exception when sqlstate '42501' then ok:=false;end;
 return jsonb_build_object('state','issued','run_id',v.id,'authorized',ok,'recovery',true);
end $function$

