CREATE OR REPLACE FUNCTION public.media_synthetic_submit(p_submission uuid, p_revision bigint, p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s submission_media.submissions;f submission_media.synthetic_fixtures;r submission_media.synthetic_reviews;h bytea;next_revision bigint;begin
 perform submission_media.require_capability('reservations');s:=submission_media.lock_owned(p_submission,null);
 select * into f from submission_media.synthetic_fixtures where submission_id=s.id and artist_id=s.owner_id;
 if not found or p_key is null then raise exception 'Registered synthetic fixture required' using errcode='42501';end if;
 select * into r from submission_media.synthetic_reviews where submission_id=s.id;
 if found then
 if r.request_key<>p_key or r.requested_revision is distinct from p_revision then raise exception 'Immutable synthetic review already exists' using errcode='40001';end if;
 return jsonb_build_object('review_id',r.id,'state',r.state,'synthetic',true,'commercial',false,'revision',s.revision);
 end if;
 if p_revision is null or p_revision<>s.revision then raise exception 'STALE_REVISION' using errcode='40001';end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('vm-test:'||f.permit_id::text,0));
 if not exists(select 1 from submission_media.jobs j where j.asset_id=f.source_id and j.job_type='source_validation' and submission_media.vm_test_valid(f.permit_id,j.id)) then raise exception 'Synthetic acceptance window closed' using errcode='42501';end if;
 if s.track_id is not null or s.working_master_id is distinct from f.source_id or s.accepted_preview_id is null or exists(select 1 from submission_media.upload_files uf join submission_media.assets a on a.id=uf.asset_id where uf.submission_id=s.id and uf.retired_at is null and a.technical_state<>'ready') then raise exception 'Complete private synthetic package required' using errcode='22023';end if;
 if (select count(distinct tj.stage) from submission_media.vm_test_jobs tj join submission_media.jobs j on j.id=tj.job_id where tj.permit_id=f.permit_id and j.state='succeeded')<>3 then raise exception 'Three verified synthetic processing stages required' using errcode='22023';end if;
 if not exists(select 1 from submission_media.assets a join storage.objects o on o.id=a.storage_object_id join storage.buckets b on b.id=o.bucket_id and not b.public where a.id=f.source_id and a.technical_state='ready' and encode(a.sha256,'hex')=f.source_sha256 and a.storage_bytes=f.source_bytes and a.storage_object_id=f.object_id and a.storage_version=f.object_version and o.version=f.object_version) or not exists(select 1 from submission_media.assets a where a.submission_id=s.id and a.source_asset_id=f.source_id and a.kind='waveform' and a.technical_state='ready') then raise exception 'Verified synthetic source and waveform required' using errcode='22023';end if;
 -- Accept only the outputs of this permit's successful stages and approved image.
 if (select count(distinct tj.stage) from submission_media.vm_test_jobs tj
 join submission_media.jobs j on j.id=tj.job_id and j.state='succeeded'
 join submission_media.assets a on a.id=j.asset_id and a.submission_id=s.id and a.source_asset_id=f.source_id and a.technical_state='ready'
 join submission_media.vm_test_permits p on p.id=tj.permit_id and a.worker_build_digest=p.build_digest
 join storage.objects o on o.id=a.storage_object_id and o.version=a.storage_version and o.bucket_id=a.bucket and o.name=a.object_path and (o.metadata->>'size')::bigint=a.storage_bytes
 join storage.buckets b on b.id=o.bucket_id and not b.public
 where tj.permit_id=f.permit_id and ((tj.stage='waveform_generation' and a.kind='waveform') or (tj.stage='preview_generation' and a.kind='buyer_preview' and a.id=s.accepted_preview_id and a.accepted_by=s.owner_id and a.accepted_at is not null)))<>2 then raise exception 'Exact private verified synthetic outputs required' using errcode='22023';end if;
 h:=submission_media.package_hash(f.source_id,s.accepted_preview_id);
 if h is null then raise exception 'Validated source and accepted preview required' using errcode='22023';end if;
 next_revision:=submission_media.bump(s.id);
 insert into submission_media.synthetic_reviews(submission_id,artist_id,source_id,preview_id,package_hash,request_key,requested_revision)
 values(s.id,s.owner_id,f.source_id,s.accepted_preview_id,h,p_key,p_revision) returning * into r;
 return jsonb_build_object('review_id',r.id,'state',r.state,'synthetic',true,'commercial',false,'revision',next_revision);
end$function$

CREATE OR REPLACE FUNCTION public.media_synthetic_review_queue()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform submission_media.require_capability('reads');perform submission_media.require_actor('admin');
 if auth.jwt()->>'aal' is distinct from 'aal2' then raise exception 'Admin MFA required' using errcode='42501';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('submission_id',r.submission_id,'review_id',r.id,'state',r.state,'requested_at',r.requested_at,'label','SYNTHETIC QA — TECHNICAL REVIEW ONLY; NOT LEGALLY CLEARED') order by r.requested_at,r.id) from submission_media.synthetic_reviews r),'[]'::jsonb);
end$function$
